"""Self-contained setup presentation. No remote assets or framework runtime."""
from html import escape
import base64
import hashlib

CSS = '''
:root{color-scheme:light;--paper:#f7f8f4;--ink:#183b37;--muted:#576d67;--line:#dce5dc;--accent:#176c57;--wash:#eaf1e8;--error:#8a3929}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:15px;line-height:1.6}a{color:var(--accent);text-underline-offset:4px}button,input{font:inherit}button,a,input{touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #bd791f;outline-offset:4px}header{max-width:1200px;margin:auto;padding:30px 40px;display:flex;justify-content:space-between;align-items:center;gap:18px}.brand{font-size:23px;font-weight:730;letter-spacing:-1px}.brand span{font-weight:430}.mark{display:inline-flex;width:30px;height:30px;align-items:center;justify-content:center;margin-right:10px;background:var(--ink);color:var(--paper);border-radius:9px;font-size:22px}.local{font-size:11px;letter-spacing:1.5px;font-weight:700;display:flex;align-items:center;gap:8px}.dot{width:7px;height:7px;border-radius:50%;background:#4c8062}main{max-width:1200px;margin:26px auto 50px;padding:0 40px;display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:start}.intro{padding:30px 0}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:750;color:var(--accent);text-transform:uppercase}.intro h1{font-size:clamp(40px,4.5vw,62px);font-weight:520;line-height:1.08;letter-spacing:-2.8px;margin:20px 0 24px;max-width:470px}.intro h1 em{font-style:normal;color:var(--accent)}.intro>p{font-size:17px;max-width:390px;color:var(--muted);line-height:1.75}.principles{margin-top:42px;max-width:395px}.principle{display:grid;grid-template-columns:34px 1fr;gap:12px;padding:17px 0;border-top:1px solid var(--line)}.principle b{font-size:14px;font-weight:650}.principle p{margin:3px 0 0;font-size:13px;color:var(--muted)}.number{font-size:11px;font-variant-numeric:tabular-nums;padding-top:4px;color:var(--accent)}.card{border:1px solid var(--line);background:#fff;border-radius:20px;padding:32px;box-shadow:0 10px 40px #183b3706}.steps{list-style:none;padding:0;margin:0 0 32px;display:flex;gap:12px;font-size:11px;color:var(--muted)}.steps li{flex:1;border-top:3px solid var(--line);padding-top:10px}.steps li.current{border-color:var(--accent);font-weight:750;color:var(--accent)}.steps li.done{border-color:#a9c9b4}.card h2{font-size:27px;font-weight:620;letter-spacing:-.8px;line-height:1.2;margin:10px 0}.lead{color:var(--muted);font-size:14px;margin:0 0 25px}label.field{display:block;font-weight:620;font-size:13px;margin:20px 0 7px}input[type=text],input[type=password]{width:100%;min-height:48px;padding:12px 14px;border:1px solid #aebeb4;border-radius:8px;background:#fcfdfb;color:var(--ink)}input::placeholder{color:#798b81}.hint{font-size:12px;color:var(--muted);margin:7px 0 18px}.primary,.secondary{display:block;text-align:center;width:100%;border-radius:9px;padding:13px 16px;font-size:14px;font-weight:650;cursor:pointer;min-height:48px;margin-top:20px}.primary{background:var(--accent);color:#fff;border:1px solid var(--accent)}.primary:hover{background:#125541}.secondary{background:#fff;color:var(--accent);border:1px solid #aebeb4}.secondary:hover{background:var(--paper)}button:disabled{opacity:.6;cursor:wait}.trust{background:var(--wash);padding:14px 16px;border-radius:9px;font-size:12px;color:#39594d;margin-top:24px}.trust strong{display:block;margin-bottom:2px;color:var(--ink);font-size:13px}.card-footer{display:flex;justify-content:space-between;gap:15px;align-items:center;border-top:1px solid var(--line);padding-top:18px;margin-top:24px;font-size:12px;color:var(--muted)}.link-button{border:0;background:none;padding:0;color:var(--muted);text-decoration:underline;text-underline-offset:3px;cursor:pointer;font-size:12px}.alert{padding:14px 16px;border:1px solid #cfdfcc;border-radius:9px;background:#f2f8ef;color:#335a42;font-size:13px;margin:18px 0}.alert.error{border-color:#e9c9bf;background:#fff4f0;color:var(--error)}.alert strong{display:block}.choices{border:0;padding:0;margin:0}.choices legend{font-size:13px;font-weight:650;margin-bottom:10px}.device{display:flex;align-items:flex-start;gap:12px;padding:16px;border:1px solid var(--line);border-radius:10px;margin:10px 0;cursor:pointer}.device:has(input:checked){border-color:var(--accent);background:#f2f8f1;box-shadow:0 0 0 1px var(--accent)}.device input{margin:6px 0 0;accent-color:var(--accent);width:17px;height:17px;flex-shrink:0}.device strong{display:block;font-size:14px}.device small{display:block;color:var(--muted);font-size:12px}.tag{display:inline-block;margin-top:8px;padding:2px 7px;border-radius:4px;background:var(--wash);font-size:10px;font-weight:650;color:#3e5c4d}.selected{padding:18px;background:var(--wash);border-radius:11px;margin:20px 0}.selected strong{font-size:18px;display:block}.selected small{display:block;color:var(--muted)}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);border-radius:10px;overflow:hidden;margin:16px 0}.metric{background:#fff;padding:13px;font-size:11px;color:var(--muted)}.metric b{display:block;color:var(--ink);font-size:19px;font-weight:550;margin-top:4px}.empty{padding:20px;background:var(--paper);border:1px dashed #b8c8ba;border-radius:10px;font-size:14px}.empty strong{display:block}.empty p{margin:7px 0;color:var(--muted)}details{font-size:13px;margin:20px 0}summary{cursor:pointer;color:var(--accent);font-weight:600}.success-icon{width:45px;height:45px;display:grid;place-items:center;background:var(--wash);color:var(--accent);border-radius:50%;font-size:24px;margin:12px 0 22px}.footer{max-width:1200px;margin:auto;padding:20px 40px 30px;display:flex;justify-content:space-between;gap:16px;font-size:11px;color:var(--muted)}[hidden]{display:none!important}.timer{font-variant-numeric:tabular-nums}code{font-size:12px;overflow-wrap:anywhere}@media(max-width:900px){main{gap:32px;padding:0 24px}header,.footer{padding-left:24px;padding-right:24px}.card{padding:24px}.intro h1{font-size:46px}}@media(max-width:680px){header{padding:20px}.local{font-size:9px;letter-spacing:1px}main{display:block;margin:10px auto 28px;padding:0 16px}.intro{padding:5px 8px 22px}.intro h1{font-size:36px;letter-spacing:-1.5px;margin:10px 0}.intro>p{font-size:14px;margin:12px 0 0}.principles{display:none}.card{padding:23px 20px;border-radius:15px}.steps{margin-bottom:24px}.footer{padding:10px 24px 24px;display:block}.footer span{display:block;margin-top:4px}}
'''
JS = '''
document.querySelectorAll('time[datetime]').forEach(el=>{const d=new Date(el.dateTime);if(!Number.isNaN(d.valueOf()))el.textContent=new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(d);});
const clock = document.querySelector('[data-seconds]');
const deadline = Date.now() + Number(clock?.dataset.seconds || 0) * 1000;
function tick(){if(!clock)return;const s=Math.max(0,Math.ceil((deadline-Date.now())/1000));clock.textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0');if(!s){document.getElementById('expired').hidden=false;document.querySelectorAll('button').forEach(b=>b.disabled=true);}}
if(clock){tick();setInterval(tick,1000);}
document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',()=>{form.setAttribute('aria-busy','true');form.querySelectorAll('button').forEach(button=>{button.disabled=true;button.textContent=button.dataset.busy||'Working…';});}));
'''

def digest(text):
    return base64.b64encode(hashlib.sha256(text.encode()).digest()).decode()

CSP = ("default-src 'none'; style-src 'sha256-" + digest(CSS) + "'; script-src 'sha256-" + digest(JS)
       + "'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'")

def form(csrf, action, body, label, secondary=False):
    busy = {'login':'Signing in…','select':'Checking capabilities…','status':'Reading status…'}.get(action, 'Working…')
    return (f'<form method="post" action="/"><input type="hidden" name="csrf" value="{escape(csrf,quote=True)}">'
            f'<input type="hidden" name="action" value="{action}">{body}'
            f'<button class="{"secondary" if secondary else "primary"}" data-busy="{busy}">{label}</button></form>')

def shell(title, lead, body, step=0, seconds=None, csrf=None, notice='', error=False):
    progress=''.join(f'<li class="{"current" if i==step else "done" if i<step else ""}"'+(' aria-current="step"' if i==step else '')+f'>{i+1:02d} &nbsp; {name}</li>' for i,name in enumerate(['Sign in','Choose device','Ready']))
    alert = '<div role="alert" class="alert'+(' error' if error else '')+'">'+escape(notice)+'</div>' if notice else ''
    ending=''
    if seconds is not None and csrf:
        ending=(f'<div class="card-footer"><span>Private session · <span class="timer" data-seconds="{max(0,int(seconds))}">5:00</span> left</span>'
                f'<form method="post" action="/"><input type="hidden" name="csrf" value="{escape(csrf,quote=True)}"><input type="hidden" name="action" value="cancel"><button class="link-button">Cancel setup</button></form></div>')
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} · openMirAIe</title><style>{CSS}</style></head><body>
<header><div class="brand"><span class="mark" aria-hidden="true">≈</span><span>open</span>MirAIe</div><div class="local"><span class="dot"></span> LOCAL SETUP</div></header>
<main><section class="intro" aria-label="About openMirAIe"><div class="eyebrow">Made for the devices you own</div><h1>Your home.<br><em>Your controls.</em></h1><p>Connect MirAIe to your assistant, with a clear view of your devices and a choice behind every change.</p>
<div class="principles"><div class="principle"><span class="number">01</span><div><b>A direct connection</b><p>Use your existing Panasonic account. No extra account or hosted service.</p></div></div><div class="principle"><span class="number">02</span><div><b>You decide what happens</b><p>Setup only connects and reads. Appliance changes start with your request.</p></div></div><div class="principle"><span class="number">03</span><div><b>See what is actually reported</b><p>Readings, support limits and connection state stay visible. Nothing is silently polled.</p></div></div></div></section>
<section class="card" aria-labelledby="page-title"><ol class="steps" aria-label="Setup progress">{progress}</ol><h2 id="page-title">{escape(title)}</h2><p class="lead">{escape(lead)}</p>{alert}<div id="expired" class="alert error" role="alert" hidden><strong>This setup session has expired.</strong>Return to your assistant and ask to open MirAIe setup again. Do not resubmit this form.</div>{body}{ending}</section></main>
<footer class="footer"><span>openMirAIe · Open tools for your home.</span><span>Unofficial integration for Panasonic MirAIe India.</span></footer><script>{JS}</script></body></html>'''
